question.answer:
class Instrument:
    def __init__(self, tag: str, reading: float) -> None:
        self.tag = tag
        self.reading = reading
        self._recalibrations = 0

    def describe(self) -> str:
        return f"{self.tag} reads {self.reading}"

    def recalibrate(self, reading: float) -> None:
        self.reading = reading
        self._recalibrations += 1


def first_reading(tag: str, reading: float) -> str:
    return Instrument(tag, reading).describe()


def peek_underscore(instrument: Instrument) -> str:
    return f"the underscore stopped nothing: {instrument._recalibrations}"

