question.answer:
class LeakyStation:
    readings: list[int] = []
    count: int = 0

    def __init__(self, name: str) -> None:
        self.name = name

    def add_reading(self, value: int) -> None:
        self.readings.append(value)
        self.count += 1


def leak_demo() -> str:
    north = LeakyStation("north")
    south = LeakyStation("south")
    north.add_reading(10)
    north.add_reading(12)
    return f"south sees {len(south.readings)} readings and LeakyStation.count is {LeakyStation.count}"


class Station:
    UNIT: str = "degC"

    def __init__(self, name: str) -> None:
        self.name = name
        self.readings: list[int] = []

    def add_reading(self, value: int) -> None:
        self.readings.append(value)

    def count(self) -> int:
        return len(self.readings)

    def average(self) -> float:
        if not self.readings:
            return 0.0
        return round(sum(self.readings) / len(self.readings), 1)

    def label(self) -> str:
        return f"{self.name} ({Station.UNIT})"

class Temperature:
    ABSOLUTE_ZERO: float = -273.15

    def __init__(self, celsius: float) -> None:
        self.__site = "rig-7"
        self.celsius = celsius

    @property
    def celsius(self) -> float:
        return self._celsius

    @celsius.setter
    def celsius(self, value: float) -> None:
        if value < Temperature.ABSOLUTE_ZERO:
            raise ValueError(f"{value} is below absolute zero")
        self._celsius = value

    @property
    def fahrenheit(self) -> float:
        return self._celsius * 9 / 5 + 32

    @classmethod
    def from_fahrenheit(cls, value: float) -> "Temperature":
        return cls((value - 32) * 5 / 9)

    @staticmethod
    def is_freezing(celsius: float) -> bool:
        return celsius <= 0


class BuoyTemperature(Temperature):
    pass


def peek_mangled(reading: Temperature) -> str:
    return f"_Temperature__site = {reading._Temperature__site}"

